using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Hosting;

namespace EndToEnd.Tests.Infrastructure;

/// <summary>
/// A service hosted in the test process, with its HTTP API on an in-memory TestServer.
/// TEntryPoint is any public type from the service's assembly: Program is generated by the compiler,
/// and both services have one.
/// </summary>
/// <remarks>
/// In the Production environment, as in the cluster, not in Development, the default of WebApplicationFactory:
/// appsettings.Development.json would hide what the cluster lacks. It did once: with its CORS origins a stray
/// app.UseCors() worked in the tests, and in the cluster, with no origins, Ledger failed at startup.
/// </remarks>
public sealed class ServiceFactory<TEntryPoint>(IReadOnlyDictionary<string, string?> settings)
    : WebApplicationFactory<TEntryPoint> where TEntryPoint : class
{
    protected override void ConfigureWebHost(IWebHostBuilder builder) =>
        builder.UseEnvironment(Environments.Production);

    protected override IHost CreateHost(IHostBuilder builder)
    {
        // Development turns these checks of the DI container on by itself, Production does not: a registration that
        // cannot be built, or a scoped service taken from the root, should still fail the test rather than production.
        builder.UseDefaultServiceProvider(options =>
        {
            options.ValidateScopes = true;
            options.ValidateOnBuild = true;
        });

        // Program.cs reads its connection strings before builder.Build(), while app configuration added by the factory
        // arrives only after that (dotnet/aspnetcore#37680). Host configuration is passed to the service's Main
        // as command-line arguments, so the service sees these values from its first line.
        builder.ConfigureHostConfiguration(configuration => configuration.AddInMemoryCollection(settings));
        return base.CreateHost(builder);
    }
}
